```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    struct Plateau { int wartosc; int pozycja; int dlugosc; };
    vector<Plateau> plateaux;

    int curDl = 1, curStart = 0;
    for (int i = 1; i <= n; i++) {
        if (i < n && T[i] == T[i - 1]) {
            curDl++;
        } else {
            if (curDl >= 2)
                plateaux.push_back({T[i - 1], curStart, curDl});
            curDl = 1;
            curStart = i;
        }
    }

    // a) Wypisz wszystkie
    cout << "a) Plateau:" << endl;
    for (auto& p : plateaux)
        cout << "   wartosc=" << p.wartosc << ", pozycja=" << p.pozycja + 1
             << ", dlugosc=" << p.dlugosc << endl;

    // b) Najdluzsze
    int maxIdx = 0;
    for (int i = 1; i < (int)plateaux.size(); i++)
        if (plateaux[i].dlugosc > plateaux[maxIdx].dlugosc)
            maxIdx = i;
    cout << "b) Najdluzsze plateau: wartosc=" << plateaux[maxIdx].wartosc
         << ", dlugosc=" << plateaux[maxIdx].dlugosc
         << ", pozycja=" << plateaux[maxIdx].pozycja + 1 << endl;

    // c) Dominujace — suma dlugosci per wartosc
    map<int, int> sumy;
    for (auto& p : plateaux)
        sumy[p.wartosc] += p.dlugosc;

    int domWart = 0, domSuma = 0;
    for (auto& [wart, suma] : sumy) {
        if (suma > domSuma || (suma == domSuma && wart < domWart)) {
            domSuma = suma;
            domWart = wart;
        }
    }
    cout << "c) Dominujace plateau: wartosc=" << domWart
         << ", lacznie elementow=" << domSuma << endl;
    return 0;
}
```

**Wyjasnienie**: Skanowanie liniowe daje liste plateau. Najdluzsze szukamy przegladem liniowym. Dominujace obliczamy sumujac dlugosci plateau o tej samej wartosci w mapie.

Weryfikacja (dane: 3,3,5,5,7,7,7,7,5,5,5,3,3,3,3):
Plateau:
- 3,3 (start=0, dl=2): i=2, 5!=3, zamkniecie.
- 5,5 (start=2, dl=2): i=4, 7!=5, zamkniecie.
- 7,7,7,7 (start=4, dl=4): i=8, 5!=7, zamkniecie.
- 5,5,5 (start=8, dl=3): i=11, 3!=5, zamkniecie.
- 3,3,3,3 (start=11, dl=4): i=15 (koniec), zamkniecie.

5 plateau. Najdluzsze: 7 (dl=4) — pierwsze o dl=4, start=5.

Sumy per wartosc:
- 3: 2+4 = 6
- 5: 2+3 = 5
- 7: 4
Dominujace: wartosc=3, lacznie=6.
